+/*
+    SPDX-FileCopyrightText: 2026 Peder Bergan
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include <CalendarEvents/CalendarEventsPlugin>
+#include <QQmlComponent>
+#include <QQmlEngine>
+#include <QTest>
+
+class CalendarEventsTest : public QObject
+{
+    Q_OBJECT
+private Q_SLOTS:
+    void location_data();
+    void location();
+};
+
+void CalendarEventsTest::location_data()
+{
+    QTest::addColumn<QString>("eventLocation");
+    QTest::newRow("absent") << QString();
+    QTest::newRow("room-and-address") << QStringLiteral("Room 4B, 12 Example Street");
+    QTest::newRow("unicode") << QStringLiteral("Møterom, 日本橋");
+    QTest::newRow("plain-text") << QStringLiteral("<b>Room 4B</b> & reception");
+    QTest::newRow("long") << QStringLiteral("A very long address with several buildings and meeting rooms. ").repeated(20);
+}
+
+void CalendarEventsTest::location()
+{
+    QFETCH(QString, eventLocation);
+    QQmlEngine engine;
+    QQmlComponent component(&engine);
+    component.setData(
+        "import org.kde.plasma.workspace.calendar\nCalendar { "
+        "days: 7; weeks: 6; displayedDate: new Date() }",
+        QUrl());
+    std::unique_ptr<QObject> calendar(component.create());
+    QVERIFY2(calendar, qPrintable(component.errorString()));
+    QObject *model = calendar->property("daysModel").value<QObject *>();
+    QVERIFY(model);
+    const QDate date = QDate::currentDate();
+    CalendarEvents::EventData event;
+    event.setUid(QStringLiteral("location-test"));
+    event.setTitle(QStringLiteral("Planning meeting"));
+    event.setStartDateTime(QDateTime(date, QTime(10, 0)));
+    event.setEndDateTime(QDateTime(date, QTime(11, 0)));
+    event.setLocation(eventLocation);
+    QMultiHash<QDate, CalendarEvents::EventData> data{{date, event}};
+    QVERIFY(QMetaObject::invokeMethod(model, "onDataReady", data));
+    auto compareLocation = [&](const QString &expected) {
+        QVariantList events;
+        QVERIFY(QMetaObject::invokeMethod(model, "eventsForDate", Q_RETURN_ARG(QVariantList, events), Q_ARG(QDate, date)));
+        QCOMPARE(events.size(), 1);
+        const QJSValue location = engine.toScriptValue(events).property(0).property(QStringLiteral("location"));
+        QVERIFY(location.isString());
+        QCOMPARE(location.toString(), expected);
+    };
+    compareLocation(eventLocation);
+    event.setLocation(QStringLiteral("Room 9, another address"));
+    QVERIFY(QMetaObject::invokeMethod(model, "onEventModified", Q_ARG(CalendarEvents::EventData, event)));
+    compareLocation(event.location());
+    event.setLocation(QString());
+    QVERIFY(QMetaObject::invokeMethod(model, "onEventModified", Q_ARG(CalendarEvents::EventData, event)));
+    compareLocation(QString());
+}
+
+QTEST_GUILESS_MAIN(CalendarEventsTest)
+#include "calendareventstest.moc"
